import * as THREE from 'three';
import { dist2 } from '../core/math.js';
import { box, ico, part } from '../core/geometry.js';
import { vcMesh } from '../gfx/core.js';
import { G, R } from '../state.js';
import { sfx } from '../audio/audio.js';
